use vstd::prelude::*;

verus! {
    /// Reverse the contents of a slice.
    ///
    /// Ensures that the result has exactly the same length as the input
    /// and that for all valid indices `i`, 
    ///   result[i] == a[a.len() - 1 - i].
    fn reverse(a: &[i32]) -> Vec<i32>
        ensures
            // same length
            result.len() == a.len(),
            // every element is at the flipped position
            forall |i: usize| i < a.len() ==> result[i] == a[a.len() - 1 - i],
    {
        // Pre-allocate a vector with the same length as the input slice.
        let mut result = Vec::with_capacity(a.len());
        // Iterate over the input slice in reverse order and push each element.
        for &value in a.iter().rev() {
            result.push(value);
        }
        result
    }
}

